      select p_league_id, p_manager_id, p_kind, p_body, p_href
       where p_manager_id is not null;
    $$;

    revoke all on function notify_manager(uuid, uuid, text, text, text) from public;

    /** Marks every unread notice read. */
    create or replace function read_notices(p_league_id uuid)
    returns int
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_me   managers;
      v_read int;
    begin
      select * into v_me from managers where auth_user_id = auth.uid();
      if v_me.id is null or v_me.league_id <> p_league_id then
        raise exception 'Not your league' using errcode = '42501';
      end if;

      update notices set read_at = now()
       where manager_id = v_me.id and read_at is null;

      get diagnostics v_read = row_count;
      return v_read;
    end;
    $$;

    revoke all on function read_notices(uuid) from public;
    grant execute on function read_notices(uuid) to authenticated;

    -- ------------------------------------------------------- what gets announced ---

    /**
     * The waiver run, re-emitted from 0024 so that it tells people.
     *
     * A claim that wins and a claim that loses are both news, and losing is the
     * one nobody would otherwise find out about: the player simply appears on
     * somebody else's roster. The reason the database recorded is the reason the
     * manager is given, because inventing a friendlier one would make the log and
     * the message disagree.
     */
    create or replace function process_waivers(p_league_id uuid)
    returns jsonb
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_claim    waiver_claims;
      v_won      int := 0;
      v_lost     int := 0;
      v_cleared  int := 0;
      v_held     int := 0;
      v_max      int;
      v_guard    int := 0;
    begin
      loop
        select c.* into v_claim
          from waiver_claims c
          join managers m on m.id = c.manager_id
          left join waiver_wire w
            on w.league_id = c.league_id and w.player_name = c.add_player
         where c.league_id = p_league_id
           and c.status = 'pending'
           and (w.player_name is null or w.clears_at <= now())
         order by m.waiver_priority, c.claim_order, c.created_at
         limit 1;

        exit when v_claim.id is null;

        v_guard := v_guard + 1;
        exit when v_guard > 10000;

        begin
          perform place_player(
            p_league_id, v_claim.manager_id,
            v_claim.add_player, v_claim.drop_player, 'waiver'
          );

          update waiver_claims
             set status = 'won', settled_at = now()
           where id = v_claim.id;

          select max(waiver_priority) into v_max
            from managers where league_id = p_league_id;

          update managers
             set waiver_priority = waiver_priority - 1
           where league_id = p_league_id
             and waiver_priority > (
               select waiver_priority from managers where id = v_claim.manager_id
             );

          update managers set waiver_priority = v_max where id = v_claim.manager_id;

          perform notify_manager(p_league_id, v_claim.manager_id, 'waiver',
            'You won ' || v_claim.add_player || ' on waivers.', '/free-agents');

          v_won := v_won + 1;

        exception when others then
          update waiver_claims
             set status = 'lost', reason = sqlerrm, settled_at = now()
           where id = v_claim.id;

          perform notify_manager(p_league_id, v_claim.manager_id, 'waiver',
            'Your claim for ' || v_claim.add_player || ' did not go through: ' || sqlerrm,
            '/free-agents');

          v_lost := v_lost + 1;
        end;
      end loop;

      delete from waiver_wire
       where league_id = p_league_id and clears_at <= now();
      get diagnostics v_cleared = row_count;

      select count(*) into v_held from waiver_wire where league_id = p_league_id;

      return jsonb_build_object('ok', true, 'won', v_won, 'lost', v_lost,
                                'cleared', v_cleared, 'stillOnWaivers', v_held);
    end;
    $$;

    revoke all on function process_waivers(uuid) from public;

    /**
     * A trade offer arriving, and a trade going through.
     *
     * Written as triggers rather than into execute_trade, because an offer is
     * created by a plain insert from the browser and countered by a plain update,
     * and there is no function to put it in. The trigger fires for the service
     * key too, which is correct: an offer is news to its recipient however it got
     * there.
     */
    create or replace function notice_on_trade()
    returns trigger
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_from text;
      v_to   text;
    begin
      select franchise into v_from from managers where id = new.from_manager;
      select franchise into v_to   from managers where id = new.to_manager;

      if tg_op = 'INSERT' then
        perform notify_manager(new.league_id, new.to_manager, 'trade',
          v_from || ' has offered you a trade.', '/trade-builder');
        return new;
      end if;

      -- A counter is the other side sending it back with different terms, so the
      -- news goes to whoever did not just change it.
      if new.status = 'countered' and old.status is distinct from 'countered' then
        perform notify_manager(new.league_id,
          case when new.to_accepted then new.from_manager else new.to_manager end,
          'trade', 'Your trade has been countered.', '/trade-builder');

      elsif new.status = 'executed' and old.status is distinct from 'executed' then
        perform notify_manager(new.league_id, new.from_manager, 'trade',
          'Your trade with ' || v_to || ' has gone through.', '/lineup');
        perform notify_manager(new.league_id, new.to_manager, 'trade',
          'Your trade with ' || v_from || ' has gone through.', '/lineup');

      elsif new.status = 'declined' and old.status is distinct from 'declined' then
        perform notify_manager(new.league_id, new.from_manager, 'trade',
          v_to || ' declined your offer.', '/trade-builder');

      elsif new.status = 'rescinded' and old.status is distinct from 'rescinded' then
        perform notify_manager(new.league_id,
          case when new.from_accepted then new.to_manager else new.from_manager end,
          'trade', 'A trade offer was withdrawn.', '/trade-builder');
      end if;

      return new;
    end;
    $$;

    drop trigger if exists trades_notice_insert on trades;
    create trigger trades_notice_insert
      after insert on trades
      for each row execute function notice_on_trade();

    drop trigger if exists trades_notice_update on trades;
    create trigger trades_notice_update
      after update on trades
      for each row execute function notice_on_trade();

    /**
     * Your turn to pick.
     *
     * Fires when the clock starts on a new pick, which is exactly the moment the
     * league moves on: current_pick changing is the draft's own definition of
     * somebody being on the clock, so there is no second thing to keep in step.
     */
    create or replace function notice_on_the_clock()
    returns trigger
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_up uuid;
    begin
      if new.draft_state <> 'running' then return new; end if;
      if new.current_pick is not distinct from old.current_pick then return new; end if;

      select manager_id into v_up
        from draft_picks
       where league_id = new.id and overall = new.current_pick;

      perform notify_manager(new.id, v_up, 'draft', 'You are on the clock.', '/draft');
      return new;
    end;
    $$;

    drop trigger if exists leagues_notice_clock on leagues;
    create trigger leagues_notice_clock
      after update on leagues
      for each row execute function notice_on_the_clock();

    -- ------------------------------------------------------------- the reset ---
    --
    -- reset_league has now been re-emitted three times in three migrations for no
    -- reason but to add a table to its delete list, copying ninety lines each time
    -- to change one. The list is its own thing, so it becomes its own function:
    -- the next table to be added is one line here, and reset_league stops being
    -- something that has to be rewritten to stay correct.

    /**
     * Deletes everything that belongs to a season rather than to the league.
     *
     * Kept: the league, its franchises, their names and divisions and PINs, the
     * settings, the admin log. Gone: everything those franchises did.
     */
    create or replace function purge_league_season(p_league_id uuid)
    returns void
    language plpgsql
    security definer
    set search_path = public
    as $$
    begin
      delete from roster_slots     where league_id = p_league_id;
      delete from matchups         where league_id = p_league_id;
      delete from player_scores    where league_id = p_league_id;
      delete from transactions     where league_id = p_league_id;
      delete from waiver_claims    where league_id = p_league_id;
      delete from waiver_wire      where league_id = p_league_id;
      delete from trades           where league_id = p_league_id;
      delete from trade_block      where league_id = p_league_id;
      delete from draft_queue      where league_id = p_league_id;
      delete from pickem_picks     where league_id = p_league_id;
      delete from playoff_seeds    where league_id = p_league_id;
      delete from league_champions where league_id = p_league_id;
      -- A notice is a thing that happened. None of it happened now.
      delete from notices          where league_id = p_league_id;
    end;
    $$;

    revoke all on function purge_league_season(uuid) from public;

    create or replace function reset_league(
      p_league_id uuid,
      p_release_franchises boolean default false
    )
    returns jsonb
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_me        managers;
      v_players   int;
      v_weeks     int;
      v_played    int;
      v_released  int := 0;
      v_saved     int;
    begin
      select * into v_me from managers where auth_user_id = auth.uid();
      if v_me.id is null or not v_me.is_commissioner or v_me.league_id <> p_league_id then
        raise exception 'Only the commissioner can reset the league' using errcode = '42501';
      end if;

      select count(*) into v_players from roster_slots where league_id = p_league_id;
      select count(distinct week) into v_weeks from matchups where league_id = p_league_id;
      select count(*) into v_played from matchups where league_id = p_league_id and final;

      v_saved := snapshot_rosters(p_league_id, 'league_reset');

      perform purge_league_season(p_league_id);

      update managers m
         set waiver_priority = seq.rn,
             ready = false
        from (
          select id, row_number() over (order by slot) as rn
            from managers where league_id = p_league_id
        ) seq
       where seq.id = m.id;

      if p_release_franchises then
        update managers
           set pin_hash = null,
               auth_user_id = null,
               name = 'Open'
         where league_id = p_league_id
           and not is_commissioner;
        get diagnostics v_released = row_count;
      end if;

      delete from draft_picks where league_id = p_league_id;
      perform rebuild_draft_board(p_league_id);

      update leagues
         set draft_state = 'pending',
             current_pick = 1,
             pick_started_at = null,
             lottery_order = null
       where id = p_league_id;

      insert into admin_log (league_id, actor, action, detail)
      values (p_league_id, v_me.id, 'league_reset',
              jsonb_build_object('players_returned', v_players,
                                 'weeks_removed', v_weeks,
                                 'weeks_played', v_played,
                                 'franchises_released', v_released,
                                 'roster_rows_saved', v_saved));

      return jsonb_build_object(
        'ok', true,
        'playersReturned', v_players,
        'weeksRemoved', v_weeks,
        'weeksPlayed', v_played,
        'franchisesReleased', v_released,
        'rosterRowsSaved', v_saved
      );
    end;
    $$;

    revoke all on function reset_league(uuid, boolean) from public;
    grant execute on function reset_league(uuid, boolean) to authenticated;

    insert into schema_migrations (name) values ('0028_notices.sql');
    raise notice 'applied %', '0028_notices.sql';
  end if;
end
$__migration__$;


-- ======================================================================
-- 0029_next_season.sql
-- ======================================================================

do $__migration__$
begin
  if exists (select 1 from schema_migrations where name = '0029_next_season.sql') then
    raise notice 'skipping %, already applied', '0029_next_season.sql';
  else
    -- Rolling the league into next year.
    --
    -- This is a dynasty league and nothing carried it forward. Every piece of the
    -- next season existed — picks awarded for 2027, a champion recorded for 2026,
    -- rosters that are supposed to be kept — and there was no way to get from one
    -- to the other. The season would simply have ended and stayed ended.
    --
    -- What a dynasty rollover is, exactly: the rosters stay, and everything that
    -- was true only of last year goes. That is the whole difference between this
    -- and reset_league, which throws the rosters away too.
    --
    --   Kept:  every roster, exactly as it stands. The franchises, their names,
    --          divisions, PINs and settings. The record book. The picks already
    --          awarded and traded for the coming draft.
    --   Gone:  the schedule and every result, the scores, the bracket and its
    --          seeds, live waiver claims and the wire, open trade offers, the
    --          trade block, draft queues and pick-'em picks.
    --   Reset: the season number, the draft board, waiver order, and the ready
    --          flags.
    --
    -- The transaction log is NOT cleared. "Where did he go?" is a question about a
    -- player who is still on somebody's roster, and in a dynasty the answer may be
    -- three years old. That is the only thing here that outlives its season on
    -- purpose.
    --
    -- Refused until the season is actually over, because a rollover in week nine
    -- is not a rollover, it is a reset that lies about what it did.

    /**
     * Starts the next season, keeping the rosters.
     *
     * The picks for the new season are awarded here rather than left to the
     * nightly job, so that the league wakes up in the new year with a draft to
     * hold rather than an empty board and a wait.
     *
     * p_season exists for a commissioner who needs to skip a year or correct one;
     * left alone it is simply the year after this one.
     */
    create or replace function roll_season(p_league_id uuid, p_season int default null)
    returns jsonb
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_me      managers;
      v_league  leagues;
      v_next    int;
      v_kept    int;
      v_weeks   int;
      v_saved   int;
      v_picks   jsonb;
      v_champ   text;
    begin
      select * into v_me from managers where auth_user_id = auth.uid();
      if v_me.id is null or not v_me.is_commissioner or v_me.league_id <> p_league_id then
        raise exception 'Only the commissioner can start the next season' using errcode = '42501';
      end if;

      select * into v_league from leagues where id = p_league_id for update;
      if v_league.id is null then
        raise exception 'No such league' using errcode = 'P0002';
      end if;

      v_next := coalesce(p_season, v_league.season + 1);
      if v_next <= v_league.season then
        raise exception 'The next season must come after % ', v_league.season
          using errcode = '22023';
      end if;

      -- A season is over when there is a champion. That is a stronger test than
      -- "every week is graded": it also rules out a league whose regular season
      -- finished last night and whose bracket has not been played.
      if not exists (
        select 1 from league_champions
         where league_id = p_league_id and season = v_league.season
      ) then
        raise exception 'The % season has no champion yet — it is not over', v_league.season
          using errcode = '55000';
      end if;

      select franchise into v_champ
        from league_champions where league_id = p_league_id and season = v_league.season;

      select count(*) into v_kept from roster_slots where league_id = p_league_id;
      select count(distinct week) into v_weeks from matchups where league_id = p_league_id;

      -- Photographed on the way past, like every other destructive thing in here.
      -- The rosters survive this, but a rollover run by mistake is still the sort
      -- of thing somebody wants back.
      v_saved := snapshot_rosters(p_league_id, 'season_roll');

      -- Everything that was true only of last season. Rosters and the record book
      -- are deliberately not in this list.
      delete from matchups      where league_id = p_league_id;
      delete from player_scores where league_id = p_league_id;
      delete from waiver_claims where league_id = p_league_id;
      delete from waiver_wire   where league_id = p_league_id;
      delete from trade_block   where league_id = p_league_id;
      delete from draft_queue   where league_id = p_league_id;
      delete from pickem_picks  where league_id = p_league_id;
      delete from playoff_seeds where league_id = p_league_id and season = v_league.season;
      delete from notices       where league_id = p_league_id;

      -- An offer names players against a season that no longer exists, and a pick
      -- for a draft that has now happened. Declined rather than deleted, so a
      -- manager's work leaves a trace rather than vanishing.
      update trades
         set status = 'declined'
       where league_id = p_league_id
         and status in ('open', 'countered', 'agreed');

      -- Everybody keeps their players; nobody keeps their lineup. Last year's
      -- starters mean nothing against a schedule that does not exist yet, and a
      -- player on IR in December is not necessarily hurt in September.
      update roster_slots
         set lineup_slot = 'BENCH',
             overall_pick = null
       where league_id = p_league_id;

      -- Waiver order back to the league's own order. Last season's rolling order
      -- is a consequence of last season.
      update managers m
         set waiver_priority = seq.rn,
             ready = false
        from (
          select id, row_number() over (order by slot) as rn
            from managers where league_id = p_league_id
        ) seq
       where seq.id = m.id;

      update leagues
         set season = v_next,
             draft_state = 'pending',
             current_pick = 1,
             pick_started_at = null,
             draft_at = null,
             -- A lottery is drawn for one draft, and the next order comes from the
             -- record instead.
             lottery_order = null
       where id = p_league_id;

      -- The board for the new draft, and the picks to fill it. award_draft_picks
      -- leaves alone any pick already created and traded, which is the whole point
      -- of having awarded them a year early.
      delete from draft_picks where league_id = p_league_id;
      v_picks := award_draft_picks(p_league_id, v_next);
      perform rebuild_draft_board(p_league_id);

      insert into admin_log (league_id, actor, action, detail)
      values (p_league_id, v_me.id, 'season_rolled',
              jsonb_build_object('from', v_league.season, 'to', v_next,
                                 'champion', v_champ, 'players_kept', v_kept,
                                 'weeks_removed', v_weeks, 'roster_rows_saved', v_saved));

      return jsonb_build_object(
        'ok', true,
        'from', v_league.season,
        'season', v_next,
        'champion', v_champ,
        'playersKept', v_kept,
        'weeksRemoved', v_weeks,
        'rosterRowsSaved', v_saved,
        'picks', v_picks
      );
    end;
    $$;

    revoke all on function roll_season(uuid, int) from public;
    grant execute on function roll_season(uuid, int) to authenticated;

    insert into schema_migrations (name) values ('0029_next_season.sql');
    raise notice 'applied %', '0029_next_season.sql';
  end if;
end
$__migration__$;


-- ======================================================================
-- 0030_watchlist.sql
-- ======================================================================

do $__migration__$
begin
  if exists (select 1 from schema_migrations where name = '0030_watchlist.sql') then
    raise notice 'skipping %, already applied', '0030_watchlist.sql';
  else
    -- Players a manager is keeping an eye on.
    --
    -- Player news has always been the wire filtered to your own roster, which
    -- answers half the question. The other half is the player you do not own yet
    -- and are deciding about — the one whose hamstring you want to hear about
    -- before you spend a waiver claim on him. A roster cannot express that.
    --
    -- Deliberately not a roster: no capacity, no positions, no effect on anything.
    -- Watching a player is a note to yourself, and the only thing that reads it is
    -- the news filter.
    --
    -- Keyed on the manager rather than the league because a manager belongs to one
    -- league anyway, and it makes "is this mine" a primary-key lookup rather than
    -- a policy that has to think about it.

    create table if not exists watchlist (
      manager_id  uuid not null references managers(id) on delete cascade,
      player_name text not null,
      league_id   uuid not null references leagues(id) on delete cascade,
      added_at    timestamptz not null default now(),
      primary key (manager_id, player_name)
    );

    create index if not exists watchlist_league_idx on watchlist (league_id);

    alter table watchlist enable row level security;

    -- Yours alone, in every direction. Who else is watching a player is exactly
    -- the sort of thing a league would rather not broadcast before a waiver run.
    drop policy if exists watchlist_own on watchlist;
    create policy watchlist_own on watchlist
      for all using (manager_id = (select id from current_manager()))
      with check (
        manager_id = (select id from current_manager())
        and league_id = (select league_id from current_manager())
      );

    grant select, insert, delete on watchlist to authenticated;

    -- A full league reset unmakes the season, and a watchlist is a note about
    -- players in it. A season ROLLOVER deliberately does not clear it: in a
    -- dynasty the player you were tracking in December is the player you are
    -- drafting in August.
    create or replace function purge_league_season(p_league_id uuid)
    returns void
    language plpgsql
    security definer
    set search_path = public
    as $$
    begin
      delete from roster_slots     where league_id = p_league_id;
      delete from matchups         where league_id = p_league_id;
      delete from player_scores    where league_id = p_league_id;
      delete from transactions     where league_id = p_league_id;
      delete from waiver_claims    where league_id = p_league_id;
      delete from waiver_wire      where league_id = p_league_id;
      delete from trades           where league_id = p_league_id;
      delete from trade_block      where league_id = p_league_id;
      delete from draft_queue      where league_id = p_league_id;
      delete from pickem_picks     where league_id = p_league_id;
      delete from playoff_seeds    where league_id = p_league_id;
      delete from league_champions where league_id = p_league_id;
      delete from notices          where league_id = p_league_id;
      delete from watchlist        where league_id = p_league_id;
    end;
    $$;

    revoke all on function purge_league_season(uuid) from public;

    insert into schema_migrations (name) values ('0030_watchlist.sql');
    raise notice 'applied %', '0030_watchlist.sql';
  end if;
end
$__migration__$;


-- ======================================================================
-- 0031_live_scoring.sql
-- ======================================================================

do $__migration__$
begin
  if exists (select 1 from schema_migrations where name = '0031_live_scoring.sql') then
    raise notice 'skipping %, already applied', '0031_live_scoring.sql';
  else
    -- Making live scoring actually live.
    --
    -- Until now the only thing that wrote player_scores was a scheduler: five
    -- minutes on game days from GitHub Actions, once a day from vercel.json. That
    -- is three things a league has to get right before a score moves — the
    -- workflow's secrets set, the right days listed, GitHub not running late —
    -- and it is still five minutes behind at its best. A Saturday game in
    -- December is not on its list at all.
    --
    -- Now a page that shows a score also fetches one. The obvious objection to
    -- that is the right one: there is no "the page". Every serverless instance is
    -- its own process with its own memory, so an in-process cache bounds nothing,
    -- and twelve managers refreshing during a Sunday slate would put an unbounded
    -- number of requests through an undocumented API that owes us nothing. The
    -- first thing that happens when you do that is you stop getting answers.
    --
    -- So the throttle lives here, where every instance can see it. Postgres is the
    -- one thing they all share. The schedulers stay exactly as they are: they are
    -- what keeps a league correct on a Tuesday when nobody has opened the site.

    create table if not exists score_refresh (
      league_id    uuid not null references leagues(id) on delete cascade,
      week         int  not null,
      -- Deliberately in the past by default, so the very first look refreshes.
      refreshed_at timestamptz not null default 'epoch',
      primary key (league_id, week)
    );

    -- No policies, on purpose. Nothing but the ingestion has any business reading
    -- or writing this, and the ingestion holds the service key, which is not
    -- subject to RLS. A table with RLS enabled and no policy denies everyone else
    -- by default, which is exactly the intent.
    alter table score_refresh enable row level security;

    -- ---------------------------------------------------------------------------
    -- Claiming a refresh
    -- ---------------------------------------------------------------------------

    -- Returns true to exactly one caller per window, and false to everyone else.
    --
    -- The claim is the timestamp bump itself, in one statement, so two instances
    -- arriving in the same millisecond cannot both win: the second one's ON
    -- CONFLICT sees the row the first one already moved and its WHERE fails.
    --
    -- There is no separate "in progress" flag and no lock held across the ESPN
    -- request, because a lock held across a network call to somebody else's server
    -- is a lock you will one day have to break by hand. Claiming optimistically
    -- means a refresh that dies mid-flight costs one window's delay — twenty-odd
    -- seconds — and then the next caller tries again. That is the right trade for
    -- a fantasy score.
    create or replace function claim_score_refresh(
      p_league_id uuid,
      p_week int,
      p_stale_seconds int
    )
    returns boolean
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_claimed boolean;
    begin
      -- Never let a caller pass a window so small it becomes a way to hammer
      -- ESPN through us.
      if p_stale_seconds < 10 then
        p_stale_seconds := 10;
      end if;

      insert into score_refresh (league_id, week, refreshed_at)
      values (p_league_id, p_week, now())
      on conflict (league_id, week) do update
        set refreshed_at = now()
        where score_refresh.refreshed_at < now() - make_interval(secs => p_stale_seconds)
      returning true into v_claimed;

      return coalesce(v_claimed, false);
    end;
    $$;

    revoke all on function claim_score_refresh(uuid, int, int) from public;

    -- How long ago the week's scores were last pulled, so a page can say so and a
    -- caller can decide whether it is worth asking.
    create or replace function score_freshness(p_league_id uuid, p_week int)
    returns timestamptz
    language sql
    stable
    security definer
    set search_path = public
    as $$
      select refreshed_at from score_refresh
       where league_id = p_league_id and week = p_week;
    $$;

    revoke all on function score_freshness(uuid, int) from public;

    -- ---------------------------------------------------------------------------
    -- Resetting
    -- ---------------------------------------------------------------------------

    -- A reset unmakes the scores, so it has to unmake the record of when they were
    -- last fetched too — otherwise the new season's week one would sit behind a
    -- throttle set by the old one's.
    create or replace function purge_league_season(p_league_id uuid)
    returns void
    language plpgsql
    security definer
    set search_path = public
    as $$
    begin
      delete from roster_slots     where league_id = p_league_id;
      delete from matchups         where league_id = p_league_id;
      delete from player_scores    where league_id = p_league_id;
      delete from score_refresh    where league_id = p_league_id;
      delete from transactions     where league_id = p_league_id;
      delete from waiver_claims    where league_id = p_league_id;
      delete from waiver_wire      where league_id = p_league_id;
      delete from trades           where league_id = p_league_id;
      delete from trade_block      where league_id = p_league_id;
      delete from draft_queue      where league_id = p_league_id;
      delete from pickem_picks     where league_id = p_league_id;
      delete from playoff_seeds    where league_id = p_league_id;
      delete from league_champions where league_id = p_league_id;
      delete from notices          where league_id = p_league_id;
      delete from watchlist        where league_id = p_league_id;
    end;
    $$;

    revoke all on function purge_league_season(uuid) from public;

    -- ---------------------------------------------------------------------------
    -- Grading a week, and knowing which week
    -- ---------------------------------------------------------------------------

    -- The week a league is grading is week N of *its* season. The old test asked
    -- whether every nfl_games row numbered N was complete, across every season and
    -- every part of every season the mirror had ever seen.
    --
    -- That is one dynasty rollover away from being wrong in the worst direction:
    -- last season's week 3 is complete for ever, so a league in its second season
    -- could have week 3 declared over — records written, playoff seeding moved —
    -- on the strength of games played a year earlier. It also lets a preseason
    -- fixture, which no fantasy team plays, hold a week open.
    --
    -- Everything else about this function is unchanged.
    create or replace function grade_week(p_league_id uuid, p_week int)
    returns jsonb
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_m        matchups;
      v_complete boolean;
      v_graded   int := 0;
      v_home     numeric;
      v_away     numeric;
      v_season   int;
    begin
      select season into v_season from leagues where id = p_league_id;
      if v_season is null then
        return jsonb_build_object('ok', false, 'error', 'no such league');
      end if;

      -- A week with no games mirrored yet cannot be closed.
      select count(*) > 0 and bool_and(completed)
        into v_complete
        from nfl_games
       where week = p_week
         and season = v_season
         and season_type = 2;

      for v_m in
        select * from matchups
         where league_id = p_league_id and week = p_week and not final
      loop
        v_home := lineup_points(p_league_id, v_m.home_manager, p_week);
        v_away := lineup_points(p_league_id, v_m.away_manager, p_week);

        update matchups
           set home_points = v_home,
               away_points = v_away,
               home_starters = (
                 select coalesce(jsonb_agg(jsonb_build_object('name', player_name, 'slot', lineup_slot)), '[]'::jsonb)
                   from roster_slots
                  where manager_id = v_m.home_manager and lineup_slot not in ('BENCH', 'IR')
               ),
               away_starters = (
                 select coalesce(jsonb_agg(jsonb_build_object('name', player_name, 'slot', lineup_slot)), '[]'::jsonb)
                   from roster_slots
                  where manager_id = v_m.away_manager and lineup_slot not in ('BENCH', 'IR')
               ),
               winner = case
                 when not coalesce(v_complete, false) then null
                 when v_home > v_away then v_m.home_manager
                 when v_away > v_home then v_m.away_manager
                 else null
               end,
               is_tie = coalesce(v_complete, false) and v_home = v_away,
               final = coalesce(v_complete, false),
               graded_at = now()
         where id = v_m.id;

        v_graded := v_graded + 1;
      end loop;

      return jsonb_build_object('ok', true, 'week', p_week, 'graded', v_graded, 'final', coalesce(v_complete, false));
    end;
    $$;

    revoke all on function grade_week(uuid, int) from public;

    -- Reading the mirror by season and week is now the hot path for both grading
    -- and the home page's "is this week being played" question.
    create index if not exists nfl_games_season_week_idx
      on nfl_games (season, season_type, week);

    insert into schema_migrations (name) values ('0031_live_scoring.sql');
    raise notice 'applied %', '0031_live_scoring.sql';
  end if;
end
$__migration__$;


-- ======================================================================
-- 0032_stat_lines.sql
-- ======================================================================

do $__migration__$
begin
  if exists (select 1 from schema_migrations where name = '0032_stat_lines.sql') then
    raise notice 'skipping %, already applied', '0032_stat_lines.sql';
  else
    -- The numbers behind the number.
    --
    -- A score on its own is a thing to be argued about. "18.4" beside a name tells
    -- a manager nothing about whether his receiver was quiet or whether the app
    -- lost half a box score, and the only way to settle it is to go and look
    -- somewhere else. The stat line is what makes the score legible.
    --
    -- Kept as structured JSON rather than as the sentence to be shown, because the
    -- wording depends on the position and the position is better known where the
    -- line is displayed than where it is written. The roster knows a man is a
    -- tight end even when he never entered our draft pool and ESPN forgot to say;
    -- the ingestion, looking only at a box score, does not always.
    --
    -- player_scores already carries a stat_line column holding a sentence written
    -- without regard to position. It stays, and stays written, so that a row from
    -- before this migration still shows something rather than a blank.

    alter table player_scores
      add column if not exists stats jsonb;

    comment on column player_scores.stats is
      'Structured stat line: completions, attempts, passYards, carries, targets, '
      'receptions, recYards, touchdowns by kind, and for a unit sacks, takeaways, '
      'fumblesRecovered, pointsAllowed, yardsAllowed, kickReturnTd, puntReturnTd. '
      'Formatted for display by src/lib/scoring.ts formatStatLine(), which decides '
      'the wording from the position. Null on rows written before 0032.';

    insert into schema_migrations (name) values ('0032_stat_lines.sql');
    raise notice 'applied %', '0032_stat_lines.sql';
  end if;
end
$__migration__$;


-- ======================================================================
-- 0033_draft_clock_and_autodraft.sql
-- ======================================================================

do $__migration__$
begin
  if exists (select 1 from schema_migrations where name = '0033_draft_clock_and_autodraft.sql') then
    raise notice 'skipping %, already applied', '0033_draft_clock_and_autodraft.sql';
  else
    -- A clock that shortens as the draft goes on, a queue you can actually set,
    -- and a switch that drafts for you.
    --
    -- Three things that belong together, because they are the same evening. Ninety
    -- seconds is right for the first round and absurd for the fourteenth, by which
    -- point the room is picking kickers and waiting on a clock nobody is using.
    -- The queue has existed since 0003 and no screen has ever written to it, so the
    -- autodraft it was built to feed has never had anything to read. And a manager
    -- who cannot be there ought to be able to say so, rather than leaving eleven
    -- people to sit out their clock every round.

    -- ------------------------------------------------------------ the clock ---

    /**
     * How long the pick in a given round gets.
     *
     * The tiers live in settings.pickClock as an ordered array — the first tier
     * whose throughRound covers the round wins, and a tier with a null
     * throughRound covers everything after it:
     *
     *   [{"throughRound": 4, "seconds": 90},
     *    {"throughRound": 10, "seconds": 75},
     *    {"throughRound": null, "seconds": 60}]
     *
     * A league from before this migration has only settings.pickSeconds, a single
     * number for the whole draft, so that is the fallback — and ninety seconds
     * behind that, because a draft with no clock at all is a draft that never
     * advances past the first person who walks away from their laptop.
     *
     * Malformed entries are skipped rather than raised on. This is read on the
     * path that makes a pick, and a typo in a settings blob must not be able to
     * stop a draft.
     */
    create or replace function pick_seconds_for(p_settings jsonb, p_round int)
    returns int
    language plpgsql
    immutable
    set search_path = public
    as $$
    declare
      v_round    int := greatest(1, coalesce(p_round, 1));
      v_settings jsonb := coalesce(p_settings, '{}'::jsonb);
      v_tier     jsonb;
      v_through  text;
      v_seconds  text;
      v_legacy   text;
    begin
      if jsonb_typeof(v_settings -> 'pickClock') = 'array' then
        for v_tier in select * from jsonb_array_elements(v_settings -> 'pickClock') loop
          if jsonb_typeof(v_tier) <> 'object' then continue; end if;

          -- A nought is a typo, not a clock, so the tier is skipped rather than
          -- clamped up to five seconds. draft-clock.ts skips it for the same
          -- reason, and the two have to agree: one draws the countdown and the
          -- other decides when the pick is taken.
          v_seconds := v_tier ->> 'seconds';
          if v_seconds is null or v_seconds !~ '^[0-9]+$' or v_seconds::int <= 0 then
            continue;
          end if;

          v_through := v_tier ->> 'throughRound';
          if v_through is null then
            return least(600, greatest(5, v_seconds::int));
          end if;
          if v_through ~ '^[0-9]+$' and v_through::int >= v_round then
            return least(600, greatest(5, v_seconds::int));
          end if;
        end loop;
      end if;

      v_legacy := v_settings ->> 'pickSeconds';
      if v_legacy is not null and v_legacy ~ '^[0-9]+$' and v_legacy::int > 0 then
        return least(600, greatest(5, v_legacy::int));
      end if;

      return 90;
    end;
    $$;

    grant execute on function pick_seconds_for(jsonb, int) to authenticated, anon;

    -- Every league that has not been told otherwise gets the tiers the league
    -- asked for. A league already carrying a pickClock is left alone; one carrying
    -- only the old single pickSeconds is moved onto the tiers, which is the point
    -- of the change rather than a side effect of it.
    update leagues
       set settings = coalesce(settings, '{}'::jsonb) || jsonb_build_object(
             'pickClock', jsonb_build_array(
               jsonb_build_object('throughRound', 4,  'seconds', 90),
               jsonb_build_object('throughRound', 10, 'seconds', 75),
               jsonb_build_object('throughRound', null, 'seconds', 60)
             ))
     where jsonb_typeof(coalesce(settings, '{}'::jsonb) -> 'pickClock') is distinct from 'array';

    /**
     * Gives the manager on the clock more time, or less.
     *
     * Re-emitted from 0018 for one reason: the limit it works against is now the
     * round's, not the league's. Everything else is as it was — moving
     * pick_started_at is still the only honest way to add time, because the
     * countdown twelve browsers are drawing is that instant plus the clock.
     */
    create or replace function nudge_clock(p_league_id uuid, p_seconds int)
    returns jsonb
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_me      managers;
      v_league  leagues;
      v_round   int;
      v_limit   int;
      v_started timestamptz;
    begin
      select * into v_me from managers where auth_user_id = auth.uid();
      if v_me.id is null or not v_me.is_commissioner or v_me.league_id <> p_league_id then
        raise exception 'Only the commissioner can change the clock' using errcode = '42501';
      end if;

      if p_seconds < -600 or p_seconds > 600 then
        raise exception 'Ten minutes either way is the most the clock moves'
          using errcode = '22003';
      end if;

      select * into v_league from leagues where id = p_league_id for update;

      if v_league.draft_state <> 'running' or v_league.pick_started_at is null then
        raise exception 'Nobody is on the clock' using errcode = '55000';
      end if;

      select round into v_round
        from draft_picks
       where league_id = p_league_id and overall = v_league.current_pick;

      v_limit := pick_seconds_for(v_league.settings, v_round);
      v_started := v_league.pick_started_at + make_interval(secs => p_seconds);

      -- Taking time away must not hand somebody an already-dead clock: the worst
      -- it can do is leave five seconds, which is a warning rather than a verdict.
      if v_started + make_interval(secs => v_limit) < now() + interval '5 seconds' then
        v_started := now() + interval '5 seconds' - make_interval(secs => v_limit);
      end if;

      update leagues set pick_started_at = v_started where id = p_league_id;

      insert into admin_log (league_id, actor, action, detail)
      values (p_league_id, v_me.id, 'clock_nudged', jsonb_build_object('seconds', p_seconds));

      return jsonb_build_object(
        'ok', true,
        'pickStartedAt', v_started,
        'remaining', extract(epoch from (v_started + make_interval(secs => v_limit) - now()))::int
      );
    end;
    $$;

    revoke all on function nudge_clock(uuid, int) from public;
    grant execute on function nudge_clock(uuid, int) to authenticated;

    -- ------------------------------------------------------------ the queue ---

    /**
     * Replaces a manager's draft queue with the list they just arranged.
     *
     * A whole-list write rather than add-one and remove-one, because a queue is
     * an order and every edit to it — dragging the fourth name to the top,
     * dropping the second — renumbers most of the rows anyway. One call, one
     * transaction, and the row policy on draft_queue is never asked to reason
     * about a half-applied reorder.
     *
     * Blank names are dropped and duplicates collapse to their first place in the
     * list, so the queue that comes back is always one that can be drafted from
     * top to bottom.
     */
    create or replace function set_draft_queue(p_league_id uuid, p_players text[])
    returns jsonb
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_me    managers;
      v_given int;
    begin
      select * into v_me from managers where auth_user_id = auth.uid();
      if v_me.id is null then
        raise exception 'Not signed in' using errcode = '28000';
      end if;
      if v_me.league_id <> p_league_id then
        raise exception 'Not your league' using errcode = '42501';
      end if;

      v_given := coalesce(array_length(p_players, 1), 0);
      if v_given > 150 then
        raise exception 'A queue holds at most 150 players, not %', v_given
          using errcode = '22023';
      end if;

      delete from draft_queue
       where league_id = p_league_id and manager_id = v_me.id;

      if v_given > 0 then
        insert into draft_queue (league_id, manager_id, player_name, rank)
        select p_league_id, v_me.id, u.name, u.ord
          from unnest(p_players) with ordinality as u(name, ord)
         where u.name is not null and length(btrim(u.name)) > 0
        on conflict (manager_id, player_name) do nothing;
      end if;

      return jsonb_build_object(
        'ok', true,
        'count', (select count(*) from draft_queue
                   where league_id = p_league_id and manager_id = v_me.id)
      );
    end;
    $$;

    revoke all on function set_draft_queue(uuid, text[]) from public;
    grant execute on function set_draft_queue(uuid, text[]) to authenticated;

    -- --------------------------------------------------------- the autodraft ---

    -- A manager who will not be at the draft, saying so. Their own to set, like
    -- ready is, and nobody else's: the column grant is the whole of what is needed
    -- because managers_self_update already limits a session to its own row.
    alter table managers
      add column if not exists autodraft boolean not null default false;

    grant update (autodraft) on managers to authenticated;

    /**
     * Picks for a manager who is not going to pick for themselves.
     *
     * Re-emitted from 0003, which fired on one condition — the clock has run out —
     * and worked against one league-wide clock. Two changes:
     *
     *   The clock is the round's now, so a fourteenth-round pick expires after a
     *   minute rather than after the ninety seconds the first round gets.
     *
     *   A manager who has switched autodraft on does not wait for a clock at all.
     *   That is the difference between "nobody is home" and "I told you I would
     *   not be": the second should not cost the other eleven a minute a round.
     *
     * The order of preference is unchanged and is the whole point of the queue:
     * the manager's own list first, skipping anyone already taken, and only then
     * the fallback the caller worked out. The fallback is passed in rather than
     * computed here because the player pool lives in the app, not the database.
     */
    create or replace function autodraft_expired(p_league_id uuid, p_fallback text default null)
    returns jsonb
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_league leagues;
      v_pick   draft_picks;
      v_name   text;
      v_auto   boolean;
      v_limit  int;
      v_reason text;
    begin
      select * into v_league from leagues where id = p_league_id for update;

      if v_league.id is null or v_league.draft_state <> 'running' then
        return jsonb_build_object('ok', false, 'reason', 'not running');
      end if;

      select * into v_pick
        from draft_picks
       where league_id = p_league_id and overall = v_league.current_pick;

      if v_pick.id is null or v_pick.player_name is not null then
        return jsonb_build_object('ok', false, 'reason', 'no open pick');
      end if;

      select coalesce(autodraft, false) into v_auto
        from managers where id = v_pick.manager_id;

      v_limit := pick_seconds_for(v_league.settings, v_pick.round);

      if v_league.pick_started_at is not null
         and now() >= v_league.pick_started_at + make_interval(secs => v_limit) then
        v_reason := 'clock';
      elsif coalesce(v_auto, false) then
        v_reason := 'autodraft';
      else
        return jsonb_build_object('ok', false, 'reason', 'on the clock');
      end if;

      -- The manager's own queue first, skipping anyone already taken.
      select q.player_name into v_name
        from draft_queue q
       where q.manager_id = v_pick.manager_id
         and not exists (
           select 1 from roster_slots r
            where r.league_id = p_league_id and r.player_name = q.player_name
         )
       order by q.rank
       limit 1;

      if v_name is not null then
        v_reason := v_reason || '_queue';
      else
        v_name := p_fallback;
      end if;

      if v_name is null then
        return jsonb_build_object('ok', false, 'reason', 'nothing to pick');
      end if;

      -- The fallback was worked out before this row was locked, so it can name
      -- somebody who has since been taken. Better to say so and be called again
      -- than to raise a unique violation out of a background job.
      if exists (
        select 1 from roster_slots
         where league_id = p_league_id and player_name = v_name
      ) then
        return jsonb_build_object('ok', false, 'reason', 'already rostered');
      end if;

      insert into roster_slots (league_id, manager_id, player_name, acquired, overall_pick, lineup_slot)
      values (p_league_id, v_pick.manager_id, v_name, 'draft', v_pick.overall, 'BENCH');

      update draft_picks
         set player_name = v_name, picked_at = now()
       where id = v_pick.id;

      delete from draft_queue where league_id = p_league_id and player_name = v_name;

      update leagues
         set current_pick = v_league.current_pick + 1,
             pick_started_at = now(),
             draft_state = case
               when v_league.current_pick + 1
                    > (select count(*) from draft_picks where league_id = p_league_id)
               then 'complete' else 'running' end
       where id = p_league_id;

      insert into admin_log (league_id, actor, action, detail)
      values (p_league_id, v_pick.manager_id, 'autodraft',
              jsonb_build_object('overall', v_pick.overall, 'player_name', v_name,
                                 'reason', v_reason));

      return jsonb_build_object('ok', true, 'overall', v_pick.overall,
                                'player_name', v_name, 'reason', v_reason);
    end;
    $$;

    revoke all on function autodraft_expired(uuid, text) from public;

    insert into schema_migrations (name) values ('0033_draft_clock_and_autodraft.sql');
    raise notice 'applied %', '0033_draft_clock_and_autodraft.sql';
  end if;
end
$__migration__$;


-- ======================================================================
-- 0034_notice_mail.sql
-- ======================================================================

do $__migration__$
begin
  if exists (select 1 from schema_migrations where name = '0034_notice_mail.sql') then
    raise notice 'skipping %, already applied', '0034_notice_mail.sql';
  else
    -- Email: the half of 0028 that was left out on purpose.
    --
    -- Notices work, and they are the right shape — written inside the transaction
    -- that causes them, so a notice cannot arrive without its cause. What they
    -- have never had is a way out of the browser. A manager who is not on the site
    -- is told nothing, which matters on exactly the two occasions that decide
    -- whether people enjoy a season: draft night, and Sunday morning with an
    -- illegal lineup.
    --
    -- So this adds a delivery channel rather than a second notification system.
    -- Every notice already written by every function that announces something is
    -- eligible; nothing that raises a notice needs to change, or knows this exists.

    -- ------------------------------------------------------------ the address ---

    -- Nullable on purpose. A league runs perfectly well with nobody's address in
    -- it — they simply get the in-app notices they already had — and a manager who
    -- would rather not hand over an email should not be made to.
    alter table managers
      add column if not exists email text,
      add column if not exists email_notices boolean not null default true;

    -- A manager owns their own address and their own choice about being emailed,
    -- the same way they own their franchise name. The row policy from 0001 already
    -- limits a session to its own row, so the column grant is the whole of it.
    grant update (email, email_notices) on managers to authenticated;

    -- --------------------------------------------------------------- the queue ---

    alter table notices
      add column if not exists emailed_at timestamptz;

    -- Only the unsent are ever looked for, and they are a vanishing fraction of an
    -- inbox that only grows — so the index covers those rows and no others.
    create index if not exists notices_unsent_idx
      on notices (created_at) where emailed_at is null;

    -- Everything that already existed counts as delivered. Without this, the first
    -- run after switching mail on would post a season of history to twelve people
    -- at once, which is the sort of thing that gets an app filtered as spam by the
    -- only twelve addresses that matter.
    update notices set emailed_at = now() where emailed_at is null;

    /**
     * Claims a batch of notices to email, and marks them claimed.
     *
     * Claim-then-send rather than send-then-mark, so two overlapping cron runs
     * cannot post the same notice twice: the first marks the rows, the second
     * finds nothing. SKIP LOCKED is what makes that true under concurrency without
     * either run waiting on the other.
     *
     * The cost of that order is a notice lost when the provider fails mid-send.
     * That is what release_notice_mail below is for — the caller hands back
     * anything it could not deliver and the next run picks it up, the same
     * claim-and-restore shape the intro-video cleanup uses.
     *
     * Only rows from the last day are eligible. A cron that has been down for a
     * week should resume, not deliver the week.
     */
    create or replace function claim_notice_mail(p_limit int default 25)
    returns table (
      notice_id  uuid,
      email      text,
      franchise  text,
      kind       text,
      body       text,
      href       text
    )
    language plpgsql
    security definer
    set search_path = public
    as $$
    begin
      return query
      with claimed as (
        select n.id
          from notices n
          join managers m on m.id = n.manager_id
         where n.emailed_at is null
           and n.created_at > now() - interval '1 day'
           and m.email is not null
           and m.email_notices
         order by n.created_at
         limit greatest(1, least(100, coalesce(p_limit, 25)))
         for update of n skip locked
      )
      update notices n
         set emailed_at = now()
        from claimed c
        join managers m on true
       where n.id = c.id
         and m.id = n.manager_id
      returning n.id, m.email, m.franchise, n.kind, n.body, n.href;
    end;
    $$;

    revoke all on function claim_notice_mail(int) from public;
    -- Deliberately granted to nobody. Only the service key reaches this, from the
    -- cron route: a session that could claim mail could mark somebody else's
    -- notices delivered and silently stop their email.

    /**
     * Hands back notices that could not be delivered.
     *
     * A claim that is not released and not sent is a notice nobody ever gets, so
     * the send path releases everything it failed on. Releasing a notice that was
     * in fact delivered would send it twice, which is why only the caller that
     * claimed it may do this — and why it does nothing to a notice claimed by a
     * different run and already sent.
     */
    create or replace function release_notice_mail(p_ids uuid[])
    returns int
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_freed int;
    begin
      update notices
         set emailed_at = null
       where id = any (coalesce(p_ids, '{}'::uuid[]))
         and emailed_at is not null;

      get diagnostics v_freed = row_count;
      return v_freed;
    end;
    $$;

    revoke all on function release_notice_mail(uuid[]) from public;

    -- purge_league_season is deliberately NOT re-emitted here. It already deletes
    -- from notices, and the mail queue is a column on that table rather than a
    -- table of its own — so a reset clears it with everything else and the
    -- function needs no change. Re-stating it to "keep the list together" would
    -- mean maintaining a second copy of a delete list, which is exactly how the
    -- copy ends up missing a table the original has.

    insert into schema_migrations (name) values ('0034_notice_mail.sql');
    raise notice 'applied %', '0034_notice_mail.sql';
  end if;
end
$__migration__$;


-- ======================================================================
-- 0035_league_chat.sql
-- ======================================================================

do $__migration__$
begin
  if exists (select 1 from schema_migrations where name = '0035_league_chat.sql') then
    raise notice 'skipping %, already applied', '0035_league_chat.sql';
  else
    -- Somewhere to talk.
    --
    -- Everything this league does to each other happens through the app — trades,
    -- claims, a defence left in on a bye — and none of it can be commented on
    -- inside it. The activity feed and the news wire are both read-only, so the
    -- reaction to every one of those things happens in a group text, and a league
    -- whose conversation lives somewhere else is a league that lives somewhere
    -- else. Trash talk is not a nice-to-have in a dynasty league; it is most of
    -- the reason people turn up in year four.
    --
    -- Deliberately not wired into notices. Every other notice is something that
    -- happened *to* you and needs answering; a message is somebody talking, and a
    -- league of twelve would email each other several hundred times a season. The
    -- unread count on the page is the right amount of nagging for this.

    create table if not exists messages (
      id         uuid primary key default gen_random_uuid(),
      league_id  uuid not null references leagues(id) on delete cascade,
      -- Who said it. Kept even when a franchise is released so the conversation
      -- does not lose half its speakers; the cascade is on the league, not the
      -- manager, and a released franchise keeps its manager row.
      manager_id uuid not null references managers(id) on delete cascade,
      body       text not null check (length(btrim(body)) between 1 and 1000),
      created_at timestamptz not null default now()
    );

    -- The only query this table ever serves: one league's messages, newest first.
    create index if not exists messages_league_idx
      on messages (league_id, created_at desc);

    alter table messages enable row level security;

    -- Everyone in the league reads everything in it. A private message is a
    -- different feature with different rules, and half-building it here would give
    -- people somewhere to say things they think are private and are not.
    drop policy if exists messages_read on messages;
    create policy messages_read on messages
      for select using (league_id = (select league_id from current_manager()));

    -- You may say things as yourself, in your own league. Both halves are checked:
    -- without the league test a manager could post into somebody else's.
    drop policy if exists messages_write on messages;
    create policy messages_write on messages
      for insert with check (
        manager_id = (select id from current_manager())
        and league_id = (select league_id from current_manager())
      );

    -- Yours to take back, and the commissioner's to remove. Nobody else's.
    drop policy if exists messages_delete on messages;
    create policy messages_delete on messages
      for delete using (
        league_id = (select league_id from current_manager())
        and (
          manager_id = (select id from current_manager())
          or (select is_commissioner from current_manager())
        )
      );

    grant select, insert, delete on messages to authenticated;
    -- No update. An edited message is a message somebody can be misquoted from —
    -- the honest version of changing your mind is deleting it and saying the other
    -- thing, which leaves the conversation readable.

    /**
     * Stops one manager filling the room.
     *
     * Not a moderation policy — it is a guard against a stuck key, a retry loop or
     * somebody being funny for ninety seconds. Ten in a minute is far more than a
     * conversation needs and far less than a flood.
     */
    create or replace function guard_message_rate()
    returns trigger
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_recent int;
    begin
      select count(*) into v_recent
        from messages
       where manager_id = new.manager_id
         and created_at > now() - interval '1 minute';

      if v_recent >= 10 then
        raise exception 'That is a lot of messages in a minute — give it a moment'
          using errcode = '54000';
      end if;

      return new;
    end;
    $$;

    drop trigger if exists messages_rate on messages;
    create trigger messages_rate
      before insert on messages
      for each row execute function guard_message_rate();

    -- Neither the season purge nor the league reset is changed to clear this, and
    -- that is the decision rather than an oversight. A dynasty league rolling into
    -- its fifth season should not lose four years of what people said to each
    -- other — the conversation is the part of a long-running league that is
    -- actually worth keeping. Deleting the league itself still takes it, through
    -- the cascade above.

    -- Realtime, so a conversation reads like one rather than like a page that
    -- happens to change. draft_picks and leagues are already published this way.
    do $$
    begin
      alter publication supabase_realtime add table messages;
    exception
      when duplicate_object then null;
      when undefined_object then null;
    end;
    $$;

    insert into schema_migrations (name) values ('0035_league_chat.sql');
    raise notice 'applied %', '0035_league_chat.sql';
  end if;
end
$__migration__$;


-- ======================================================================
-- 0036_best_ball.sql
-- ======================================================================

do $__migration__$
begin
  if exists (select 1 from schema_migrations where name = '0036_best_ball.sql') then
    raise notice 'skipping %, already applied', '0036_best_ball.sql';
  else
    -- Best ball: nobody sets a lineup, ever.
    --
    -- The whole roster plays. Each week the highest scorers fill the starting
    -- slots by themselves, swapping as the afternoon goes on and the numbers move,
    -- and whatever the arrangement is when the last game ends is the one that
    -- counts. There is no lineup to forget to set, no player left on a bench who
    -- went for thirty, and no Sunday morning spent checking whether somebody is
    -- active.
    --
    -- The rule that decides who wins therefore lives here rather than in a
    -- browser. A result computed by whichever client happened to be open is not a
    -- result; grade_week has always asked the database what a lineup was worth,
    -- and it still does — the answer is just the best arrangement now instead of
    -- the one somebody saved.

    -- ----------------------------------------------------------- the positions ---
    --
    -- The database has never known what position anybody plays. It did not have
    -- to: lineup_slot said what a player counted as, and a manager put him there.
    -- Best ball has nobody to ask, so it needs the real thing.
    --
    -- The app is the only place that knows — the draft pool lives there — so the
    -- app writes it. In the league's own vocabulary (K, not PK; RB for a fullback)
    -- because that is what a slot is named after.

    alter table roster_slots
      add column if not exists position text;

    /**
     * Records what everybody on a roster plays.
     *
     * Sent as two parallel arrays rather than a row at a time: this is called on
     * the same schedule as the score refresh, and a hundred and fifty round trips
     * to say what has not changed is not a refresh.
     *
     * Idempotent and self-healing. Nothing depends on it having run at any
     * particular moment — a position that is missing costs that player his slot
     * for one refresh, and the next one puts him back.
     */
    create or replace function sync_roster_positions(
      p_league_id  uuid,
      p_names      text[],
      p_positions  text[]
    )
    returns int
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_changed int;
    begin
      if coalesce(array_length(p_names, 1), 0) <> coalesce(array_length(p_positions, 1), 0) then
        raise exception 'A name and a position for each, or neither' using errcode = '22023';
      end if;

      update roster_slots r
         set position = u.pos
        from unnest(p_names, p_positions) as u(name, pos)
       where r.league_id = p_league_id
         and r.player_name = u.name
         and r.position is distinct from u.pos;

      get diagnostics v_changed = row_count;
      return v_changed;
    end;
    $$;

    revoke all on function sync_roster_positions(uuid, text[], text[]) from public;
    -- The service key only. A session that could write positions could make a
    -- quarterback eligible for a flex and quietly win a week with it.

    -- ------------------------------------------------------------ the lineup ---

    /**
     * The best legal lineup a roster can field in one week, and what it is worth.
     *
     * Greedy, and greedy is provably right for this shape of lineup. Every
     * dedicated slot takes exactly one position, so the highest scorers at each
     * position must fill them — swapping in a lower one can never help. Only the
     * flex is shared, and it takes whatever is left over. A superflex would break
     * that reasoning, which is one more reason this league does not have one.
     *
     * A player with no score that week counts as nought rather than being left
     * out, so a slot filled by somebody who did not play reads as a filled slot
     * worth nothing — which is what it is.
     *
     * Ties break on name. Two players on the same points is common early on a
     * Sunday when everybody has nought, and a lineup that reshuffles itself
     * between two refreshes for no reason looks broken.
     */
    create or replace function best_ball_lineup(
      p_league_id  uuid,
      p_manager_id uuid,
      p_week       int
    )
    returns table (player_name text, slot text, points numeric)
    language plpgsql
    stable
    set search_path = public
    as $$
    declare
      v_starters jsonb;
    begin
      select coalesce(settings -> 'starters', '{}'::jsonb)
        into v_starters
        from leagues
       where id = p_league_id;

      return query
      with held as (
        select r.player_name    as name,
               coalesce(r.position, '') as pos,
               coalesce(s.points, 0)    as pts
          from roster_slots r
          left join player_scores s
            on s.league_id = r.league_id
           and s.player_name = r.player_name
           and s.week = p_week
         where r.league_id = p_league_id
           and r.manager_id = p_manager_id
           -- Injured reserve is the one thing lineup_slot still says. A player
           -- stashed there does not count against the roster, so he must not be
           -- able to score for it either.
           and coalesce(r.lineup_slot, '') <> 'IR'
      ),
      ranked as (
        select h.*,
               row_number() over (partition by h.pos order by h.pts desc, h.name) as rank_at
          from held h
      ),
      dedicated as (
        select r.name, r.pos as in_slot, r.pts
          from ranked r
         where r.pos <> ''
           and r.rank_at <= coalesce((v_starters ->> r.pos)::int, 0)
      ),
      spare as (
        select r.name, r.pts
          from ranked r
         where r.pos in ('RB', 'WR', 'TE')
           and not exists (select 1 from dedicated d where d.name = r.name)
         order by r.pts desc, r.name
         limit coalesce((v_starters ->> 'FLEX')::int, 0)
      )
      select d.name, d.in_slot, d.pts from dedicated d
      union all
      select s.name, 'FLEX', s.pts from spare s;
    end;
    $$;

    grant execute on function best_ball_lineup(uuid, uuid, int) to authenticated;

    /**
     * What a manager's week is worth.
     *
     * Re-emitted from 0008. It used to sum whoever was not on the bench, which
     * was the right answer when somebody chose who that was. Now it sums the best
     * arrangement, which is the same question with the choosing taken out.
     */
    create or replace function lineup_points(p_league_id uuid, p_manager_id uuid, p_week int)
    returns numeric
    language sql
    stable
    set search_path = public
    as $$
      select coalesce(sum(points), 0)
        from best_ball_lineup(p_league_id, p_manager_id, p_week);
    $$;

    /** The same lineup as the snapshot a graded matchup keeps. */
    create or replace function best_ball_starters(
      p_league_id  uuid,
      p_manager_id uuid,
      p_week       int
    )
    returns jsonb
    language sql
    stable
    set search_path = public
    as $$
      select coalesce(
        jsonb_agg(jsonb_build_object('name', player_name, 'slot', slot, 'points', points)),
        '[]'::jsonb
      )
      from best_ball_lineup(p_league_id, p_manager_id, p_week);
    $$;

    /**
     * Scores a week and, once its games are over, freezes the result.
     *
     * Re-emitted from 0031 with one change: the starters it photographs are the
     * best-ball lineup rather than whoever was not on a bench. Everything else —
     * when a week is allowed to close, how a tie is recorded, the refusal to
     * regrade a final week — is exactly as it was.
     *
     * That snapshot is the whole point of freezing. While the week is open the
     * lineup is recomputed on every read and moves with the scores; once the last
     * game ends it is written down, and what is written down is what stands.
     */
    create or replace function grade_week(p_league_id uuid, p_week int)
    returns jsonb
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_m        matchups;
      v_complete boolean;
      v_graded   int := 0;
      v_home     numeric;
      v_away     numeric;
      v_season   int;
    begin
      select season into v_season from leagues where id = p_league_id;
      if v_season is null then
        return jsonb_build_object('ok', false, 'error', 'no such league');
      end if;

      -- A week with no games mirrored yet cannot be closed.
      select count(*) > 0 and bool_and(completed)
        into v_complete
        from nfl_games
       where week = p_week
         and season = v_season
         and season_type = 2;

      for v_m in
        select * from matchups
         where league_id = p_league_id and week = p_week and not final
      loop
        v_home := lineup_points(p_league_id, v_m.home_manager, p_week);
        v_away := lineup_points(p_league_id, v_m.away_manager, p_week);

        update matchups
           set home_points = v_home,
               away_points = v_away,
               home_starters = best_ball_starters(p_league_id, v_m.home_manager, p_week),
               away_starters = best_ball_starters(p_league_id, v_m.away_manager, p_week),
               winner = case
                 when not coalesce(v_complete, false) then null
                 when v_home > v_away then v_m.home_manager
                 when v_away > v_home then v_m.away_manager
                 else null
               end,
               is_tie = coalesce(v_complete, false) and v_home = v_away,
               final = coalesce(v_complete, false),
               graded_at = now()
         where id = v_m.id;

        v_graded := v_graded + 1;
      end loop;

      return jsonb_build_object('ok', true, 'week', p_week, 'graded', v_graded, 'final', coalesce(v_complete, false));
    end;
    $$;

    revoke all on function grade_week(uuid, int) from public;

    -- Every league is best ball now. Recorded in settings rather than assumed, so
    -- the rules page and the lineup screen read it from the same place everything
    -- else about this league is read from.
    update leagues
       set settings = coalesce(settings, '{}'::jsonb) || '{"bestBall": true}'::jsonb;

    -- --------------------------------------------------------- injured reserve ---
    --
    -- The one decision left. Everything else about a lineup is gone, but a dynasty
    -- roster still has to be able to carry a man who tore something in October
    -- without paying a roster spot for him all season — that is a different
    -- problem from choosing who starts, and best ball does not solve it.
    --
    -- lineup_slot therefore stays on roster_slots and stops meaning anything
    -- except this: 'IR' or not. roster_count has excluded IR since 0007 and still
    -- does, so the capacity rule needs no change; best_ball_lineup above excludes
    -- it too, so a stashed player cannot score.

    /**
     * Stashes one of your own on injured reserve, or brings him back.
     *
     * Whether he is actually injured is not asked here, because this database has
     * never seen an injury report — that lives at ESPN and reaches the app, so the
     * app is what refuses to stash a fit player. What is enforced here is the part
     * that is about the league rather than about a player: it is your roster, the
     * reserve holds what the settings say it holds, and a man coming back has to
     * have a roster spot to come back to.
     */
    create or replace function set_injured_reserve(p_player text, p_on boolean)
    returns jsonb
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_me       managers;
      v_settings jsonb;
      v_limit    int;
      v_stashed  int;
      v_was_ir   boolean;
    begin
      select * into v_me from current_manager();
      if v_me.id is null then
        raise exception 'Not signed in' using errcode = '42501';
      end if;

      select settings into v_settings from leagues where id = v_me.league_id;

      select lineup_slot = 'IR'
        into v_was_ir
        from roster_slots
       where manager_id = v_me.id and player_name = p_player;

      if v_was_ir is null then
        raise exception 'You do not hold %', p_player using errcode = 'P0002';
      end if;

      if p_on then
        v_limit := coalesce((v_settings ->> 'ir')::int, 0);

        select count(*)
          into v_stashed
          from roster_slots
         where manager_id = v_me.id
           and lineup_slot = 'IR'
           and player_name <> p_player;

        if v_stashed >= v_limit then
          raise exception 'Injured reserve holds %', v_limit using errcode = '55000';
        end if;

        update roster_slots
           set lineup_slot = 'IR'
         where manager_id = v_me.id and player_name = p_player;
      else
        -- Only a player actually coming back needs room made for him; asking for
        -- BENCH twice is a no-op rather than an error somebody has to understand.
        if v_was_ir and roster_count(v_me.id) >= roster_capacity(v_settings) then
          raise exception 'Your roster is full at % — drop someone first',
            roster_capacity(v_settings) using errcode = '55000';
        end if;

        update roster_slots
           set lineup_slot = 'BENCH'
         where manager_id = v_me.id and player_name = p_player;
      end if;

      return jsonb_build_object('ok', true, 'player', p_player, 'ir', p_on);
    end;
    $$;

    grant execute on function set_injured_reserve(text, boolean) to authenticated;

    insert into schema_migrations (name) values ('0036_best_ball.sql');
    raise notice 'applied %', '0036_best_ball.sql';
  end if;
end
$__migration__$;


-- ======================================================================
-- 0037_roster_cap.sql
-- ======================================================================

do $__migration__$
begin
  if exists (select 1 from schema_migrations where name = '0037_roster_cap.sql') then
    raise notice 'skipping %, already applied', '0037_roster_cap.sql';
  else
    -- Eighteen players, not twenty-four.
    --
    -- The cap has never been a setting of its own: roster_capacity adds the
    -- starting slots to the bench, so ten starters and a bench of fourteen made
    -- twenty-four. Eighteen means a bench of eight — the same ten on the field,
    -- eight behind them, and injured reserve outside it as always.
    --
    -- The draft rounds move with it. They have always matched the roster exactly,
    -- so that a completed draft leaves every franchise full and nobody has to drop
    -- a player they just spent a pick on; twenty-four rounds into an eighteen-man
    -- roster would refuse the last six picks of every team.
    --
    -- Best ball makes the smaller number matter more than it used to. Nobody is
    -- setting a lineup, so a deep bench is no longer somewhere to stash a hunch —
    -- every player you own is playing every week, and eight of depth is a real
    -- decision about which eight rather than a wall of names nobody looks at.

    update leagues
       set settings = coalesce(settings, '{}'::jsonb)
                    || jsonb_build_object('bench', 8, 'rounds', 18);

    /**
     * Rebuilds the board to match, where that is still possible.
     *
     * rebuild_draft_board refuses once a single pick has been made, and rightly:
     * redrawing a board mid-draft would renumber picks people have already used.
     * So this asks it only for leagues that have not started, and leaves the rest
     * alone rather than failing the migration.
     *
     * A league that is already drafting keeps its twenty-four rounds and its
     * twenty-four-man rosters until the commissioner deals with it. That is the
     * honest outcome: the alternative is a board that no longer matches the picks
     * sitting on it.
     */
    do $$
    declare
      v_league uuid;
    begin
      for v_league in
        select l.id
          from leagues l
         where not exists (
           select 1 from draft_picks p
            where p.league_id = l.id and p.player_name is not null
         )
      loop
        perform rebuild_draft_board(v_league);
      end loop;
    end;
    $$;

    -- Rosters already over the new cap are not touched. roster_count is only
    -- consulted when somebody adds a player, so an over-full roster simply cannot
    -- take another until it is under eighteen — which is the rule doing its job
    -- rather than the migration deleting somebody's tight end.

    insert into schema_migrations (name) values ('0037_roster_cap.sql');
    raise notice 'applied %', '0037_roster_cap.sql';
  end if;
end
$__migration__$;


-- ======================================================================
-- 0038_full_ppr.sql
-- ======================================================================

do $__migration__$
begin
  if exists (select 1 from schema_migrations where name = '0038_full_ppr.sql') then
    raise notice 'skipping %, already applied', '0038_full_ppr.sql';
  else
    -- A point a catch.
    --
    -- The league is full PPR rather than half. One line, because the scorer has
    -- read the format from the settings since the day it was written and nothing
    -- else in the database has an opinion about receptions.
    --
    -- Worth being explicit about what this does not change: every score already
    -- recorded stays as it was. player_scores holds numbers, not the rules that
    -- produced them, and a week already graded keeps the points it was settled on.
    -- Re-scoring the season under the new rule would rewrite results people have
    -- already lived with — a matchup somebody lost by two would change hands
    -- months later. If this needs applying to weeks already played, that is a
    -- deliberate re-run of the scoring job for those weeks, not a migration.

    update leagues
       set settings = coalesce(settings, '{}'::jsonb) || '{"scoring": "ppr"}'::jsonb;

    insert into schema_migrations (name) values ('0038_full_ppr.sql');
    raise notice 'applied %', '0038_full_ppr.sql';
  end if;
end
$__migration__$;


-- ======================================================================
-- 0039_draft_sequence.sql
-- ======================================================================

do $__migration__$
begin
  if exists (select 1 from schema_migrations where name = '0039_draft_sequence.sql') then
    raise notice 'skipping %, already applied', '0039_draft_sequence.sql';
  else
    -- Draft night, in the order it actually happens.
    --
    -- The bug this fixes is the whole reason for it. Opening the room set
    -- draft_state to 'running', and 'running' does two things at once: it tells
    -- every browser the draft has begun, and it starts the pick clock. The room
    -- plays the intro film on the same signal — so the clock and the film started
    -- together, and by the time the film ended the first manager's ninety seconds
    -- were gone and the autodraft had taken his pick. The commissioner's opening
    -- act cost somebody their first-round selection.
    --
    -- The fix is to stop overloading one state with two meanings. Draft night now
    -- has four:
    --
    --   pending   nothing has happened; the countdown is running
    --   lobby     the room is open, the film plays, and then everybody waits
    --   lottery   the order is being drawn on screen, last pick to first
    --   running   round one, and only now the pick clock
    --
    -- Only 'running' carries a clock. Every guard in the draft — make_pick,
    -- autodraft_expired, nudge_clock — already refuses unless the state is
    -- 'running', so the two new states are safe by construction rather than by
    -- anybody remembering to check them.

    alter table leagues
      add column if not exists lottery_at timestamptz;

    comment on column leagues.lottery_at is
      'When the draft lottery began. Every browser animates the reveal from this '
      'instant rather than from when its own page opened, so twelve managers watch '
      'the same spin land at the same moment — and a refresh halfway through '
      'rejoins where everyone else is rather than starting again.';

    -- The set of states is now worth writing down. It has been a bare text column
    -- since 0001, guarded only by the whitelist inside set_draft_state, and this
    -- migration doubles the number of values it can hold.
    alter table leagues
      drop constraint if exists leagues_draft_state_check;

    alter table leagues
      add constraint leagues_draft_state_check
      check (draft_state in ('pending', 'lobby', 'lottery', 'running', 'paused', 'complete'));

    /**
     * Starting, pausing and resuming the draft.
     *
     * Re-emitted from 0006 with the two new states, and with one change that is
     * the point of the whole migration: the clock is cleared for every state that
     * is not 'running'. It used to be cleared only on 'paused', which left a
     * live clock ticking behind the lobby and the lottery.
     */
    create or replace function set_draft_state(p_league_id uuid, p_state text)
    returns jsonb
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_me      managers;
      v_league  leagues;
      v_open    int;
    begin
      select * into v_me from managers where auth_user_id = auth.uid();
      if v_me.id is null or not v_me.is_commissioner or v_me.league_id <> p_league_id then
        raise exception 'Only the commissioner can control the draft' using errcode = '42501';
      end if;

      if p_state not in ('pending', 'lobby', 'lottery', 'running', 'paused', 'complete') then
        raise exception 'Unknown draft state %', p_state using errcode = '22023';
      end if;

      select * into v_league from leagues where id = p_league_id for update;

      if p_state = 'running' then
        select count(*) into v_open
          from draft_picks
         where league_id = p_league_id and player_name is null;

        if v_open = 0 then
          raise exception 'Every pick has been made' using errcode = '55000';
        end if;

        -- Resume from the first pick still open, so a board that was rebuilt or a
        -- draft that was paused mid-round picks up in the right place.
        update leagues
           set draft_state = 'running',
               current_pick = (
                 select min(overall) from draft_picks
                  where league_id = p_league_id and player_name is null
               ),
               -- The clock starts here and nowhere else. A paused draft must not
               -- resume onto an expired clock and autodraft whoever was on it,
               -- and a room that is merely open must not be running one at all.
               pick_started_at = now()
         where id = p_league_id;
      else
        update leagues
           set draft_state = p_state,
               -- Cleared for every state but 'running'. A clock that keeps time
               -- behind a screen nobody can pick from is the bug this migration
               -- exists to remove.
               pick_started_at = null
         where id = p_league_id;
      end if;

      insert into admin_log (league_id, actor, action, detail)
      values (p_league_id, v_me.id, 'draft_state', jsonb_build_object('to', p_state));

      return jsonb_build_object('ok', true, 'state', p_state);
    end;
    $$;

    revoke all on function set_draft_state(uuid, text) from public;
    grant execute on function set_draft_state(uuid, text) to authenticated;

    /**
     * Draws the draft order, and starts the reveal.
     *
     * Drawn here rather than in a browser, which is where the league office has
     * always drawn it. That was fine for a commissioner setting an order in
     * advance; it is no use at all for a ceremony twelve people watch at once,
     * because twelve browsers shuffling independently would each land on a
     * different answer. One draw, on the server, written down before anybody sees
     * a thing.
     *
     * lottery_at is the starting gun. The animation is a function of how long ago
     * it was fired, so every screen is at the same point in the reveal and a
     * manager who refreshes mid-spin rejoins the others rather than starting over.
     *
     * The order itself is stored first pick first, as lottery_order always has
     * been. That the reveal runs backwards — last pick up to first, because the
     * first overall is the only one worth saving until the end — is the screen's
     * business, not the database's.
     */
    create or replace function start_lottery(p_league_id uuid)
    returns jsonb
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_me     managers;
      v_league leagues;
      v_made   int;
      v_order  text[];
    begin
      select * into v_me from managers where auth_user_id = auth.uid();
      if v_me.id is null or not v_me.is_commissioner or v_me.league_id <> p_league_id then
        raise exception 'Only the commissioner can draw the lottery' using errcode = '42501';
      end if;

      select * into v_league from leagues where id = p_league_id for update;
      if v_league.id is null then
        raise exception 'No such league' using errcode = 'P0002';
      end if;

      -- Before the draft, and only before it. Redrawing while picks are on the
      -- board would renumber selections people have already made.
      select count(*) into v_made
        from draft_picks
       where league_id = p_league_id and player_name is not null;

      if v_made > 0 then
        raise exception 'The draft has already started — the order is fixed now'
          using errcode = '55000';
      end if;

      if v_league.draft_state not in ('pending', 'lobby', 'lottery') then
        raise exception 'The lottery is drawn before the draft, not during it'
          using errcode = '55000';
      end if;

      -- Unbiased: the sort key is drawn once per row, so every ordering is as
      -- likely as every other.
      select array_agg(slot order by random())
        into v_order
        from managers
       where league_id = p_league_id;

      if coalesce(array_length(v_order, 1), 0) = 0 then
        raise exception 'This league has no franchises to draw' using errcode = '55000';
      end if;

      update leagues
         set lottery_order   = v_order,
             draft_state     = 'lottery',
             lottery_at      = now(),
             -- Nothing is on the clock during a lottery.
             pick_started_at = null
       where id = p_league_id;

      -- The board is drawn from the order, so it is redrawn now rather than left
      -- for somebody to remember. rebuild_draft_board refuses once a pick has been
      -- made, which the check above has already ruled out.
      perform rebuild_draft_board(p_league_id);

      insert into admin_log (league_id, actor, action, detail)
      values (p_league_id, v_me.id, 'draft_lottery',
              jsonb_build_object('order', to_jsonb(v_order)));

      return jsonb_build_object('ok', true, 'order', to_jsonb(v_order), 'at', now());
    end;
    $$;

    revoke all on function start_lottery(uuid) from public;
    grant execute on function start_lottery(uuid) to authenticated;

    insert into schema_migrations (name) values ('0039_draft_sequence.sql');
    raise notice 'applied %', '0039_draft_sequence.sql';
  end if;
end
$__migration__$;


commit;

